#include <stdio.h>
#include <stdlib.h>

// Define the structure for a linked list node
typedef struct Node {
    int value;
    struct Node* next;
} Node;

// Define the head of the linked list
Node* head = NULL;

// Define the used variable to keep track of the number of nodes
int used = 0;

int main(int argc, char* argv[]) {
    // Check if the number of arguments is less than 2
    if (argc < 2) {
        printf("Usage: %s <number1> <number2> ... <numberN>\n", argv[0]);
        return 1;
    }

    // Iterate over the arguments
    for (int i = 1; i < argc; i++) {
        // Convert the argument to an integer
        int num = atoi(argv[i]);

        // Create a new node
        Node* new_node = (Node*) malloc(sizeof(Node));
        new_node->value = num;
        new_node->next = NULL;

        // If the list is empty, set the head to the new node
        if (head == NULL) {
            head = new_node;
        } else {
            // Otherwise, find the correct position for the new node
            Node* current = head;
            while (current->next != NULL && current->next->value < num) {
                current = current->next;
            }

            // Insert the new node at the correct position
            new_node->next = current->next;
            current->next = new_node;
        }

        // Increment the used variable
        used++;
    }

    // Print the sorted linked list
    Node* current = head;
    while (current != NULL) {
        printf("%d ", current->value);
        current = current->next;
    }
    printf("\n");

    return 0;
}
